class Solution {
    public List<Boolean> camelMatch(String[] queries,String pattern){
        List<Boolean> answer=new ArrayList<>();
        for(String query:queries){
            int index=0;
            boolean valid=true;
            for(char ch:query.toCharArray())if(index<pattern.length()&&ch==pattern.charAt(index))index++;
            else if(Character.isUpperCase(ch)){
                valid=false;
                break;
            }
            answer.add(valid&&index==pattern.length());
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun camelMatch(queries:Array<String>,pattern:String):List<Boolean>{
        return queries.map{
            query->var index=0;
            var valid=true;
            for(ch in query)if(index<pattern.length&&ch==pattern[index])index++ else if(ch.isUpperCase()){
                valid=false;
                break
            };
            valid&&index==pattern.length
        }
    }
}

